const rj = $('Valida e Processa Callback').item.json;

const bodyHtml = `
<p><strong>Alerta:</strong> chegou uma confirmação de pagamento com um valor diferente do esperado. A landing NÃO foi publicada.</p>
<ul>
<li>Landing: ${escapeHtml(rj.titulo || '')} (${escapeHtml(rj.orderId || '')})</li>
<li>Valor esperado: €${escapeHtml(rj.valorEsperadoEuros || '')}</li>
<li>Valor recebido do gateway: ${escapeHtml(String(rj.valorRecebido || ''))}</li>
<li>URL: ${escapeHtml(rj.canonical || '')}</li>
</ul>
<p>Verifique manualmente no backoffice do gateway antes de publicar à mão.</p>
`;

const html = buildEmailPrisma({
  brandName: PRISMA_BRAND_NAME,
  preheader: 'Valor de pagamento incorreto -- landing nao publicada.',
  headline: 'Valor de pagamento incorreto',
  bodyHtml,
  ctaLabel: '',
  ctaUrl: ''
});

return [{ json: { targetEmail: rj.operatorEmail, subject: '[ALERTA] Valor de pagamento incorreto — ' + (rj.titulo || ''), html } }];

const emailResp = $json;
const falhou = !!emailResp.error;
const stateFileName = $('Valida e Processa Callback').item.json.stateFileName;

const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
let state;
try { state = JSON.parse(buf.toString('utf8')); } catch (e) {
  throw new Error('VERIFICA EMAIL: state.json ilegível ao registar o envio (' + stateFileName + ').');
}
state.email_enviado = !falhou;
state.email_verificado_em = new Date().toISOString();
if (falhou) {
  state.email_erro = String(emailResp.error);
} else {
  delete state.email_erro;
  state.email_gmail_id = emailResp.id || null;
}

const out = Buffer.from(JSON.stringify(state, null, 2), 'utf8');
return [{
  json: { emailFalhou: falhou, stateFileName, motivo: falhou ? String(emailResp.error) : '' },
  binary: { state: await this.helpers.prepareBinaryData(out, stateFileName, 'application/json') }
}];

if ($json.emailFalhou) {
  throw new Error('ENVIO DE EMAIL FALHOU (ja registado em email_erro no state.json) -- ' + $json.motivo);
}
return [{ json: {} }];

